<template>
  <div class="operation-page">
    <PageHero title="质检知识库" icon="Files" description="整理检测规范、缺陷定义与维修说明。私人资料仅本人可读，企业资料由主管发布并供企业成员检索。"><template #actions><el-button type="primary" @click="edit(null)"><AppIcon name="Upload" :size="16" />上传资料</el-button></template></PageHero>
    <form class="operation-toolbar" @submit.prevent="search"><el-input v-model="query" clearable maxlength="500" placeholder="搜索规范、缺陷定义或维修说明" aria-label="知识库检索词" /><el-button type="primary" native-type="submit" :loading="searching">全文检索</el-button><el-button :loading="loading" @click="load(1)">全部资料</el-button></form>
    <el-alert v-if="error && records.length" :title="error" type="warning" :closable="false" />
    <section v-if="searched" class="operation-panel" aria-label="全文检索结果"><h3>检索引用 · {{ hits.length }} 条</h3><p class="operation-muted">按当前可读资料的最新版本匹配文字。选择引用可定位到对应版本和段落。</p><div v-for="hit in hits" :key="hit.document_id+':'+hit.ordinal_no" class="operation-chunk"><el-button link type="primary" @click="open(hit.document_id,hit.current_version,hit.ordinal_no)">{{ hit.title }} · v{{ hit.current_version }} · {{ hit.locator }}</el-button><p class="operation-detail-copy">{{ hit.content_text }}</p><code>{{ hit.document_id }}@v{{ hit.current_version }}:{{ hit.ordinal_no }}</code></div><p v-if="!hits.length" class="operation-muted">没有匹配的可读文字资料</p></section>
    <section class="operation-cards" aria-label="知识资料列表"><article v-for="row in records" :key="row.document_id" class="operation-card"><h3>{{ row.title }}</h3><el-tag :type="row.visibility==='PRIVATE'?'info':'primary'">{{ row.visibility==='PRIVATE'?'私人资料':'企业资料' }}</el-tag><el-tag v-if="row.lifecycle==='ARCHIVED'" type="info">已归档</el-tag><p>{{ row.filename }}</p><p>v{{ row.current_version }} · 更新于 {{ utcDisplay(row.updated_at) }}</p><div class="operation-actions"><el-button @click="open(row.document_id)">查看资料</el-button></div></article></section>
    <CollectionEmptyState v-if="!records.length" :loading="loading" :error="error" empty-title="开始整理质检资料" empty-description="上传现有规范或说明，解析成功后即可检索和引用。" @retry="load(page)" />
    <el-pagination v-if="total!==null&&total>20" :current-page="page" :page-size="20" :total="total" layout="prev,pager,next" @current-change="load" />
    <el-drawer v-model="uploadVisible" :title="editing?'追加资料版本':'上传知识资料'" size="min(520px,100vw)" :close-on-click-modal="!busy" :close-on-press-escape="!busy" :before-close="closeUpload">
      <form class="operation-form" @submit.prevent="upload"><label>资料标题<el-input v-model="form.title" maxlength="180" required /></label><label>可见范围<el-select v-model="form.visibility" :disabled="!!editing&&editing.owner_user_id!==user.identity?.userId"><el-option label="私人资料" value="PRIVATE" /><el-option v-if="isSupervisor||editing?.visibility==='ENTERPRISE'" label="企业资料" value="ENTERPRISE" /></el-select></label><label>原文件<input :key="uploadKey" type="file" required accept=".txt,.md,.csv,.json,.pdf,.docx,.xlsx,.pptx" @change="selectFile" /></label><p class="operation-muted">单文件不超过 5 MiB，提取文字不超过 20 万字符。Office 仅建立文字索引；不执行公式、宏或文件中的指令。扫描件需先完成 OCR。</p><p v-if="editing" class="operation-muted">保留历史版本，将创建 v{{ editing.current_version+1 }}；不会覆盖旧文件。</p><el-alert v-if="formError" :title="formError" type="error" :closable="false" /><el-button type="primary" native-type="submit" :loading="busy" :disabled="!file||!form.title.trim()">{{ busy?'正在解析并保存':'保存并建立文字索引' }}</el-button></form>
    </el-drawer>
    <el-drawer v-model="detailVisible" title="资料与引用" size="min(760px,100vw)"><el-alert v-if="detailError" :title="detailError" type="error" :closable="false" /><p v-if="!detail&&!detailError" class="operation-muted" role="status">正在读取资料版本</p><div v-if="detail" class="operation-form"><h2>{{ detail.revision.title }}</h2><div class="operation-toolbar"><el-select :model-value="detail.revision.version" aria-label="资料版本" @change="version=>open(detail.document.document_id,version)"><el-option v-for="v in detail.versions" :key="v.version" :label="'v'+v.version+' · '+({READY:'文字索引可用',EMPTY:'暂无可检索文字'}[v.index_state]||'索引状态待核对')" :value="v.version" /></el-select><el-button :loading="busy" @click="downloadSource">下载原文件</el-button></div><p class="operation-muted">{{ detail.revision.filename }} · {{ detail.revision.chunk_count }} 个文字段落 · 原文件 SHA-256 {{ detail.revision.source_sha256 }}</p><div class="operation-actions"><el-button v-if="detail.editable&&detail.document.lifecycle==='ACTIVE'" :disabled="busy" @click="edit(detail.document)">追加版本</el-button><el-button v-if="detail.editable" :disabled="busy" @click="lifecycle">{{ detail.document.lifecycle==='ARCHIVED'?'恢复资料':'归档资料' }}</el-button></div><div class="operation-scroll" tabindex="0" role="region" aria-label="知识资料文字段落"><article v-for="chunk in detail.chunks" :id="'knowledge-chunk-'+chunk.ordinal_no" :key="chunk.ordinal_no" class="operation-chunk" :class="{'is-target':targetChunk===chunk.ordinal_no}"><h3>{{ chunk.locator }}</h3><p class="operation-detail-copy">{{ chunk.content_text }}</p></article></div><details v-if="detail.audit?.length"><summary>最近操作记录（最多 100 条）</summary><ol class="operation-scroll"><li v-for="(item,index) in detail.audit" :key="index" class="operation-muted">{{ ({INDEX:'保存版本与索引',ARCHIVE:'归档',RESTORE:'恢复',DOWNLOAD:'原文件下载'})[item.action_name]||item.action_name }} · v{{ item.version }} · 账号 {{ item.actor_user_id }} · {{ utcDisplay(item.created_at) }}</li></ol></details></div></el-drawer>
  </div>
</template>
<script setup>
import { computed, nextTick, onMounted, reactive, ref } from 'vue'
import { useRoute } from 'vue-router'
import { ElMessageBox } from 'element-plus'
import request from '../api/request'
import { useUserStore } from '../stores/user'
import { useAccountOperationScope } from '../composables/useAccountOperationScope'
import { operationData, operationError, deliverFile, utcDisplay } from '../utils/qualityOperations'
import AppIcon from '../components/AppIcon.vue'
import CollectionEmptyState from '../components/CollectionEmptyState.vue'
import '../assets/quality-operations.css'
const user=useUserStore(),route=useRoute(),isSupervisor=computed(()=>['SUPERVISOR','ADMIN'].includes(user.role))
const records=ref([]),total=ref(null),page=ref(1),loading=ref(false),error=ref(''),query=ref(''),hits=ref([]),searched=ref(false),searching=ref(false)
const detail=ref(null),detailVisible=ref(false),detailError=ref(''),targetChunk=ref(null),uploadVisible=ref(false),editing=ref(null),busy=ref(false),formError=ref(''),file=ref(null),uploadKey=ref(0),form=reactive({title:'',visibility:'PRIVATE'}),requestId=ref('')
const scope=useAccountOperationScope(()=>{records.value=[];hits.value=[];detail.value=null;total.value=null;detailVisible.value=false;uploadVisible.value=false;loading.value=false;searching.value=false;busy.value=false;error.value='';detailError.value='';formError.value='';file.value=null;editing.value=null;query.value='';form.title='';form.visibility='PRIVATE';requestId.value=''}),listing=scope.channel(),reading=scope.channel(),searchChannel=scope.channel()
const base='/api/quality/knowledge',headers={'X-Knowledge-Action':'update'}
async function load(value=1){searchChannel.begin();searching.value=false;const token=listing.begin();loading.value=true;error.value='';searched.value=false;try{const data=operationData(await request.get(base,{params:{page:value,size:20},signal:token.signal}));if(!listing.current(token))return;if(!Array.isArray(data?.records)||!Number.isSafeInteger(data.total))throw new Error('资料列表未完整读取');records.value=data.records;total.value=data.total;page.value=value}catch(e){if(listing.current(token)){records.value=[];total.value=null;error.value=operationError(e,true)}}finally{if(listing.current(token))loading.value=false}}
async function search(){if(!query.value.trim())return;const token=searchChannel.begin();searching.value=true;error.value='';try{const data=operationData(await request.get(base+'/search',{params:{query:query.value.trim()},signal:token.signal}));if(!searchChannel.current(token))return;if(!Array.isArray(data))throw new Error('检索结果未完整读取');hits.value=data;searched.value=true}catch(e){if(searchChannel.current(token)){hits.value=[];error.value=operationError(e,true)}}finally{if(searchChannel.current(token))searching.value=false}}
async function open(id,version,chunk){const token=reading.begin();detail.value=null;detailError.value='';detailVisible.value=true;targetChunk.value=chunk||null;try{const data=operationData(await request.get(base+'/'+encodeURIComponent(id),{params:{version},signal:token.signal}));if(!reading.current(token))return;if(!data?.document||!data.revision||!Array.isArray(data.chunks))throw new Error('资料版本未完整读取');detail.value=data;await nextTick();if(reading.current(token)&&chunk)document.getElementById('knowledge-chunk-'+chunk)?.scrollIntoView({block:'nearest'})}catch(e){if(reading.current(token))detailError.value=operationError(e)}}
function edit(row){if(busy.value)return;reading.begin();editing.value=row;form.title=row?.title||'';form.visibility=row?.visibility||'PRIVATE';file.value=null;uploadKey.value++;formError.value='';requestId.value=crypto.randomUUID();uploadVisible.value=true}
function selectFile(event){file.value=event.target.files?.[0]||null;if(file.value?.size>5*1024*1024){file.value=null;formError.value='原文件不超过 5 MiB'}}
function closeUpload(done){if(!busy.value)done()}
async function upload(){if(busy.value||!file.value)return;const token=scope.stamp();busy.value=true;formError.value='';const body=new FormData();body.set('title',form.title.trim());body.set('visibility',form.visibility);body.set('requestId',requestId.value);body.set('file',file.value);const row=editing.value;if(row)body.set('expectedVersion',row.revision);try{const data=operationData(await request.post(row?base+'/'+row.document_id+'/versions':base,body,{headers,timeout:60000}));if(!scope.current(token))return;uploadVisible.value=false;reading.begin();detail.value=data;detailVisible.value=true;await load(1)}catch(e){if(scope.current(token))formError.value=operationError(e)+'；重试会沿用当前请求编号，请勿重复新建'}finally{if(scope.current(token))busy.value=false}}
async function lifecycle(){if(busy.value||!detail.value)return;const token=scope.stamp(),doc=detail.value.document,archived=doc.lifecycle!=='ARCHIVED';try{await ElMessageBox.confirm(archived?'归档后停止检索，保留原文件和历史版本。':'恢复后将重新参与可见范围内的检索。',archived?'归档资料':'恢复资料',{type:'info'});if(!scope.current(token))return;busy.value=true;const data=operationData(await request.put(base+'/'+doc.document_id+'/lifecycle',{expectedVersion:doc.revision,archived,requestId:crypto.randomUUID()},{headers}));if(!scope.current(token))return;detail.value=data;await load(page.value)}catch(e){if(scope.current(token)&&e!=='cancel'&&e!=='close')detailError.value=operationError(e)}finally{if(scope.current(token))busy.value=false}}
async function downloadSource(){if(busy.value||!detail.value)return;const token=scope.stamp(),value=detail.value;busy.value=true;try{const response=await request.get(base+'/'+value.document.document_id+'/versions/'+value.revision.version+'/source',{responseType:'blob'});await deliverFile(response,value.revision.filename,['application/octet-stream'],()=>scope.current(token),value.revision.source_sha256)}catch(e){if(scope.current(token))detailError.value=operationError(e)}finally{if(scope.current(token))busy.value=false}}
onMounted(async()=>{await load();if(route.query.documentId)await open(String(route.query.documentId),route.query.version?Number(route.query.version):undefined,route.query.chunk?Number(route.query.chunk):undefined)})
</script>
